action.command:
cat > /tmp/verify/debug_output.js <<'EOF'
const { chromium } = require('playwright');
(async () => {
    const browser = await chromium.launch();
    const page = await browser.newPage();
    const toasts = [];
    page.on('console', m => { if (m.type() === 'debug' && /Collected|Will start|Request/.test(m.text())) console.log('DBG: ' + m.text()); });
    await page.goto('http://localhost/index.html', { waitUntil: 'networkidle' });
    await page.waitForTimeout(4000);
    await page.selectOption('#chooseIndex', { label: 'spotify_tracks' });
    await page.waitForTimeout(5000);
    await page.click('.oneCollapsibleItem.filter .collapsible-header');
    await page.waitForTimeout(1000);
    await page.selectOption('#dataExplorerDataFields', { index: 1 });
    await page.waitForTimeout(3000);
    await page.click('.oneCollapsibleItem.output .collapsible-header');
    await page.waitForTimeout(1000);
    await page.selectOption('.chartTypeChooser', { label: 'barChart' });
    await page.waitForTimeout(1500);
    const outHtml = await page.$eval('#outputControls', el => el.innerHTML);
    console.log('OUTPUT HTML NOW:');
    console.log(outHtml);
    await browser.close();
})().catch(e => { console.error('DBG3_FAILED', e); process.exit(1); });
EOF
cd /tmp/verify && node debug_output.js 2>&1 | head -40

